  <script>
    const menuButton=document.querySelector('.menu-toggle');const menu=document.querySelector('.nav-links');menuButton.addEventListener('click',()=>{const open=menu.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Chiudi menu':'Apri menu')});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Apri menu')}));
    const search=document.querySelector('#doc-search');const filters=[...document.querySelectorAll('.filter')];const cards=[...document.querySelectorAll('.doc-card')];let selected='all';function updateDocs(){const term=search.value.trim().toLocaleLowerCase('it');let visible=0;cards.forEach(card=>{const show=(selected==='all'||card.dataset.brand===selected)&&card.dataset.search.toLocaleLowerCase('it').includes(term);card.hidden=!show;if(show)visible++});document.querySelector('#empty').style.display=visible?'none':'block'}search.addEventListener('input',updateDocs);filters.forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.filter;filters.forEach(item=>item.setAttribute('aria-pressed',String(item===button)));updateDocs()}));
    if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}else document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'));
  </script>
